import{_ as r,l as n,o as e,c as l,v as t,p as s,x as i,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"融资融券机制","description":"","frontmatter":{"title":"融资融券机制","date":"2026-09-10T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/margin-securities-lending.md","filePath":"quant/margin-securities-lending.md","lastUpdated":1789023840000}'),c={name:"quant/margin-securities-lending.md"};function h(u,a,A,m,_,B){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="融资融券机制" tabindex="-1">融资融券机制 <a class="header-anchor" href="#融资融券机制" aria-label="Permalink to &quot;融资融券机制&quot;">​</a></h1><div class="epigraph"><p>多头杠杆借的是钱，空头杠杆借的是券；两套合约、两套可开仓名单、两套被召回的方式。回测里把空头写成负权重，等于假设券总能借到。</p><footer>—— 据 D&#39;Avolio, Journal of Financial Economics, 2002；Geczy, Musto and Reed, Journal of Financial Economics, 2002 整理</footer></div><p>上一课<a href="/quant/liquidation-gap-risk">强平与缺口风险</a>假设仓位已经存在、只是价格跳空。空头仓位能否存在，取决于融券；多头加杠杆，取决于融资。本课把保证金账户拆成<strong>借钱</strong>与<strong>借券</strong>两条腿。费率下一课专讲；本课先钉机制与回测里「可空」集合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无约束多空因子对每一只股票写正负权重。实盘空头需要找到出借人，且该券在当时的可融名单上。D&#39;Avolio 描述了借券市场的供给如何随日变化：热门空头供给紧、容易被召回。Geczy–Musto–Reed 表明部分异象的空头侧在不可借或极贵时不可实施。缺口是形成日宇宙要再交一次集：当时可融资买入、当时可融券卖出。财务课的当时上市集合是超集；本课是可实施子集。</p><p>召回（recall）会强制回补，效果类似强平，但触发的是出借人要回证券，不一定是保证金击穿。</p><h3 id="融券余额不是做空意愿的充分统计" tabindex="-1">融券余额不是做空意愿的充分统计 <a class="header-anchor" href="#融券余额不是做空意愿的充分统计" aria-label="Permalink to &quot;融券余额不是做空意愿的充分统计&quot;">​</a></h3><p>可观察到的空头利息是成交后的存量，受供给约束。供给枯竭时，想做空做不成，余额不一定大。用高空头利息当「拥挤」可以，用低空头利息当「可以自由做空」不行。回测应以可借标志与借券库存为准，而不是以事后空头利息倒推当时可开仓。</p><p><span class="marginnote">中国融资融券有标的名单与保证金比例，名单调整本身是事件。用今日标的回填历史，是制度版幸存者。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>开空前检查：该证券在 \\(t\\) 是否可借、要求的保证金、是否已被限定为只能平仓。开融资多头检查：是否在融资标的、折算率。召回到达时，按规则在限期内回补，成交价用当时可成交价，走上一课缺口逻辑。不要在回测结束时才丢掉「从未出现在借券库」的名字——那会留下易借的幸存者。</p><p>财务因子的空头往往是小市值、低质量、难借的券。可实施过滤会显著削弱纸面空头收益，这应被视为正确的衰减，不是要被「数据清洗」加回去的损失。</p>',12)),(e(),s(E,null,{default:i(()=>[p(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20UNI%5B%22%E5%BD%93%E6%97%B6%E4%B8%8A%E5%B8%82%E5%AE%87%E5%AE%99%22%5D%20--%3E%20LONG%5B%22%E5%8F%AF%E8%9E%8D%E8%B5%84%E6%A0%87%E7%9A%84%22%5D%0A%20%20UNI%20--%3E%20SHORT%5B%22%E5%8F%AF%E8%9E%8D%E5%88%B8%E6%A0%87%E7%9A%84%22%5D%0A%20%20SHORT%20--%3E%20RECALL%5B%22%E5%8F%AC%E5%9B%9E%E5%88%99%E5%BC%BA%E5%88%B6%E5%9B%9E%E8%A1%A5%22%5D%0A%20%20LIST%5B%22%E4%BB%8A%E6%97%A5%E5%90%8D%E5%8D%95%E5%9B%9E%E5%A1%AB%22%5D%20--%3E%20BIAS%5B%22%E5%8F%AF%E7%A9%BA%E5%B9%B8%E5%AD%98%E8%80%85%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>可融券名单按日求交之后，还要看是否「只能平仓、不能新开」。后者在 A 股标的调出、美股 hard-to-borrow 极端日都出现。回测把「只能平仓」写成当日空头增量上限为零、已有空头可回补。用空头利息高来反推「当时一定可借」，方向可能反了：利息高常常是供给已紧、增量更借不到。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>借券供给来自托管长仓、基金出借、库存券。供给紧时，后课费率上升，同时召回概率上升。保证金占用与借券约束叠加：即使维持线未破，召回也能把空头清掉。于是质量空头、盈余负意外空头在最拥挤时最不可实施。回测偏差的方向几乎总是：纸面策略空头赚得太多。</p><p><span class="marginnote">本课不进入限价簿谁先成交。能否借到券是开仓资格；排队与价差是后课 LOB 的事。</span></p><p>形成日负权重先与当时可融券名单求交；不在名单上则空头增量记零。召回按公告限期回补，价格走缺口规则。不要用期末才出现在借券库里的股票回填「一直可空」。A 股融资融券标的调整按生效日更新，今日标的不得覆盖历史。过滤前后空头收益的差，就是纸面异象里不可实施的那一块，应报告而不是加回。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写各市场融资融券管理办法汇编。下一课<a href="/quant/stock-loan-fee">借券费率</a>把资格变成成本。回购是机构之间的抵押融资，机制相近但合约不同，再后一课。后课默认：负权重先过当时可借检查；今日可空名单不得回填。</p><p>后课费率把资格换成成本；没有资格则费率无意义。本课过滤后的空头截面，才是质量与 PEAD 空头真正能交易的那一截。今日可空名单、期末才进入借券库的名字，都不得回填。召回走缺口，不走「按收盘自愿回补」。</p><p>后课默认负权重先过当时可借检查；今日可空名单与期末才进入借券库的名字都不得回填。</p><p>出借人召回给出限期，不是即时市价成交。限期结束时若仍停牌，回补推到复牌第一笔。召回与停牌叠加是空头最差路径，必须允许成交落在限期之后的第一可成交价，而不是在停牌日用标记价假装回补。</p><p>可融券过滤前后的空头收益差要写入回测报告，那是纸面异象里不可实施的部分，不应加回。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>融资借钱、融券借券，可开仓名单不同。</li><li>负权重 ≠ 当时可实施空头。</li><li>召回是另一类强制回补，不必等到维持线。</li><li>空头利息是存量，不是供给的充分统计。</li><li>纸面空头收益偏高，是本课要修的回测偏差。</li><li>出处：D&#39;Avolio (2002)；Geczy, Musto and Reed (2002)。</li></ul>',13))])}const D=r(c,[["render",h]]);export{q as __pageData,D as default};
